// Hand-written `fastify` stub for the flowatlas fixture suite.
//
// A route says what it reads and answers in one type argument - `Body`,
// `Querystring`, `Params`, `Headers`, `Reply` - which types the request and the
// reply its handler is handed. Without it every part is `unknown`.

export interface IncomingHttpHeaders {
  host?: string;
  [header: string]: string | string[] | undefined;
}

export interface RouteGenericInterface {
  Body?: unknown;
  Querystring?: unknown;
  Params?: unknown;
  Headers?: unknown;
  Reply?: unknown;
}

export interface FastifyRequest<G extends RouteGenericInterface = RouteGenericInterface> {
  body: G['Body'];
  query: G['Querystring'];
  params: G['Params'];
  headers: IncomingHttpHeaders;
}

export interface FastifyReply<G extends RouteGenericInterface = RouteGenericInterface> {
  code(status: number): FastifyReply<G>;
  status(status: number): FastifyReply<G>;
  send(payload?: G['Reply']): FastifyReply<G>;
}

export type RouteHandlerMethod<G extends RouteGenericInterface = RouteGenericInterface> = (
  request: FastifyRequest<G>,
  reply: FastifyReply<G>,
) => unknown;

type Verb = <G extends RouteGenericInterface = RouteGenericInterface>(
  path: string,
  handler: RouteHandlerMethod<G>,
) => FastifyInstance;

export interface FastifyInstance {
  get: Verb;
  post: Verb;
  put: Verb;
  delete: Verb;
  register(plugin: FastifyPluginAsync, options?: { prefix?: string }): FastifyInstance;
  listen(options: { port: number }): Promise<string>;
}

export type FastifyPluginAsync = (instance: FastifyInstance, options: unknown) => Promise<void>;

declare function fastify(): FastifyInstance;

export default fastify;
